        [Fact(DisplayName = "replay > reproduces a live session exactly from initial state + command log")]
        public void T002_reproduces_a_live_session_exactly_from_initial_state_command()
        {
            var initial = States.createState(new NewStateOptions { seed = 1234, width = Js.I(8), height = Js.I(6) });
            var live = States.cloneState(initial);
            for (var i = 0; i < 40; i++)
            {
                var x = JsMath.floor(((double)(Rng.random(live)) * (8)));
                var y = JsMath.floor(((double)(Rng.random(live)) * (6)));
                var type = (Rng.random(live) < 0.7) ? "placeWall" : "placeDoor";
                Commands.applyCommand(live, new Command { type = type, x = Js.I(x), y = Js.I(y) });
                Tick.step(live, 1 + JsMath.floor(((double)(Rng.random(live)) * (3))));
            }
            var replayed = Replay.replay(initial, live.commandLog, live.tick);
            expect(DebugText.dumpText(replayed)).toBe(DebugText.dumpText(live));
            expect(replayed.grid).toEqual(live.grid);
            expect(replayed.tick).toBe(live.tick);
            expect(replayed.walkabilityVersion).toBe(live.walkabilityVersion);
            expect(replayed.commandLog).toEqual(live.commandLog);
        }

        [Fact(DisplayName = "replay > gives identical full state for two replays of the same log")]
