            List<LoggedCommand> log = [new LoggedCommand { tick = 0, command = new Command { type = "placeWall", x = Js.I(1), y = Js.I(1) } }, new LoggedCommand { tick = 2, command = new Command { type = "placeDoor", x = Js.I(2), y = Js.I(1) } }, new LoggedCommand { tick = 2, command = new Command { type = "clearTile", x = Js.I(1), y = Js.I(1) } }];
            expect(Js.Json_stringify(Replay.replay(initial, log, 20))).toBe(Js.Json_stringify(Replay.replay(initial, log, 20)));
        }

